	private static void permute(char[] fields, int start, List<String> result) {
		if (start == fields.length) {
			result.add(new String(fields));
			return;
		}
		for (int i = start; i < fields.length; i++) {
			char swap = fields[start];
			fields[start] = fields[i];
			fields[i] = swap;
			permute(fields, start + 1, result);
			swap = fields[start];
			fields[start] = fields[i];
			fields[i] = swap;
		}
	}
